#!/usr/bin/env node
// scaffold-ci-pipeline.js — v78 emit .github/workflows/ci.yml that runs
// typecheck + test + build for backend AND frontend on every push/PR.
//
// Idempotent. Marker: '# Generated by scaffold-ci-pipeline'.
'use strict';

var fs = require('fs');
var path = require('path');

function parseArgs(argv) {
  var out = {};
  for (var i = 2; i < argv.length; i++) {
    var a = argv[i];
    if (a === '--target') out.target = argv[++i];
    else if (a === '--force') out.force = true;
    else if (a === '--dry-run') out.dryRun = true;
    else if (a === '--verbose' || a === '-v') out.verbose = true;
  }
  if (!out.target) { console.error('Usage: scaffold-ci-pipeline --target PROJECT_ROOT'); process.exit(1); }
  return out;
}

function marker() { return '# Generated by scaffold-ci-pipeline — DO NOT EDIT BY HAND. Re-run to refresh.'; }

function writeIfManaged(file, content, force, dryRun) {
  if (fs.existsSync(file)) {
    var existing = fs.readFileSync(file, 'utf-8');
    if (!/Generated by scaffold-ci-pipeline/.test(existing) && !force) {
      return { written: false, reason: 'exists-handauthored' };
    }
    if (existing === content) return { written: false, reason: 'unchanged' };
  }
  if (dryRun) return { written: false, reason: 'dry-run' };
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content);
  return { written: true };
}

var CI_YML = [
  '# Generated by scaffold-ci-pipeline — DO NOT EDIT BY HAND. Re-run to refresh.',
  'name: CI',
  '',
  'on:',
  '  push:',
  '    branches: [main, dev]',
  '  pull_request:',
  '',
  'concurrency:',
  '  group: ci-${{ github.ref }}',
  '  cancel-in-progress: true',
  '',
  'jobs:',
  '  backend:',
  '    runs-on: ubuntu-latest',
  '    services:',
  '      postgres:',
  '        image: postgres:16-alpine',
  '        env:',
  '          POSTGRES_USER: postgres',
  '          POSTGRES_PASSWORD: postgres',
  '          POSTGRES_DB: test',
  '        ports: ["5432:5432"]',
  '        options: >-',
  '          --health-cmd "pg_isready -U postgres" --health-interval 5s',
  '          --health-timeout 5s --health-retries 5',
  '    defaults:',
  '      run:',
  '        working-directory: backend',
  '    steps:',
  '      - uses: actions/checkout@v4',
  '      - uses: actions/setup-node@v4',
  '        with:',
  '          node-version: 20',
  "          cache: npm",
  '          cache-dependency-path: backend/package-lock.json',
  '      - run: npm ci',
  '      - run: npx tsc --noEmit',
  '      - run: npm test --if-present -- --passWithNoTests',
  '        env:',
  '          DATABASE_URL: postgres://postgres:postgres@localhost:5432/test',
  '      - run: npm run build --if-present',
  '',
  '  frontend:',
  '    runs-on: ubuntu-latest',
  '    defaults:',
  '      run:',
  '        working-directory: frontend',
  '    steps:',
  '      - uses: actions/checkout@v4',
  '      - uses: actions/setup-node@v4',
  '        with:',
  '          node-version: 20',
  "          cache: npm",
  '          cache-dependency-path: frontend/package-lock.json',
  '      - run: npm ci',
  '      - run: npx tsc --noEmit',
  '      - run: npm test --if-present -- --run',
  '      - run: npm run build',
  '',
].join('\n');

function main() {
  var args = parseArgs(process.argv);
  var dst = path.join(args.target, '.github/workflows/ci.yml');
  var r = writeIfManaged(dst, CI_YML, args.force, args.dryRun);
  console.log('scaffold-ci-pipeline: .github/workflows/ci.yml=' + (r.written ? 'wrote' : r.reason));
}

main();
